-- 官公庁・自治体の公式サイト(Issue #37)。data/public-bodies/ledger.csv から scripts/public_bodies_sql.py が生成した派生物。手で編集しない。
-- 根拠は台帳の sources 列(独立した2出典以上の一致)。紹介文は定型で、トップページの内容は読んでいない。last_crawled_at・source_updated_at は未設定。
-- registered_at は出典の確認日。bulk_import=1 は一括投入の印で、直近登録の集計・ACTIVITY・NEW タグ・既定の並びの先頭から外す(ALTER は初回のみ)。
-- 新設/追加 1851 件。
ALTER TABLE sites ADD COLUMN bulk_import INTEGER NOT NULL DEFAULT 0 CHECK (bulk_import IN (0, 1));
